import{_ as t,o,c as a,ag as d}from"./chunks/framework.TQKaXlFR.js";const h=JSON.parse('{"title":"代码结构与功能定位","description":"","frontmatter":{},"headers":[],"relativePath":"development/structure.md","filePath":"development/structure.md"}'),r={name:"development/structure.md"};function c(s,e,n,i,l,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="代码结构与功能定位" tabindex="-1">代码结构与功能定位 <a class="header-anchor" href="#代码结构与功能定位" aria-label="Permalink to &quot;代码结构与功能定位&quot;">​</a></h1><p>适用于第一次接手本项目的开发者。先完成<a href="/xinghui-admin-vue3/docs/guide/quickstart.html">快速开始</a>，确认运行的是当前前后端候选；文档中的源码路径均相对于对应仓库，不是本机路径或已发布源码浏览器链接。</p><h2 id="前端分层" tabindex="-1">前端分层 <a class="header-anchor" href="#前端分层" aria-label="Permalink to &quot;前端分层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>职责</th></tr></thead><tbody><tr><td><code>apps/web-ele/src/views/</code></td><td>当前后台页面及局部状态</td></tr><tr><td><code>apps/web-ele/src/api/</code></td><td>DTO类型、真实路径、requestClient调用</td></tr><tr><td><code>apps/web-ele/src/composables/</code></td><td>分页、字典、编辑和确认状态</td></tr><tr><td><code>apps/web-ele/src/adapter/</code></td><td>Element Plus组件、Vben Form/VXE接入</td></tr><tr><td><code>apps/web-ele/src/router/</code></td><td>核心路由、后端菜单转换、隐藏业务路由</td></tr><tr><td><code>packages/@core/</code>、<code>packages/effects/</code></td><td>上游封装及本地共享能力，不为单页随意改接口</td></tr><tr><td><code>apps/docs/content/</code></td><td>唯一文档正文来源</td></tr></tbody></table><h2 id="后端分层" tabindex="-1">后端分层 <a class="header-anchor" href="#后端分层" aria-label="Permalink to &quot;后端分层&quot;">​</a></h2><p><code>system-admin</code>提供应用启动、Controller和当前功能服务；<code>system-framework</code>承载认证过滤器等框架接缝；<code>common</code>中的core、tenant、security、redis、oss等模块提供基础能力。业务目录包括content（目前仅资讯）、lowcode、ai、notification、quartz、businessconfig。</p><p><code>system-admin/src/main/resources/db/migration/</code>保存版本迁移，optional-migration保存显式可选迁移。旧已应用版本不能因文档重整改checksum；新扩展新增版本并验证空库和升级。<a href="/xinghui-admin-vue3/docs/reference/database-migrations.html">迁移约定</a>另有详细说明。</p><h2 id="从页面追到服务" tabindex="-1">从页面追到服务 <a class="header-anchor" href="#从页面追到服务" aria-label="Permalink to &quot;从页面追到服务&quot;">​</a></h2><p>以资讯为例：<code>views/system/news/index.vue</code>调用<code>api/system/news.ts</code>，落到<code>ContentNewsController</code>，由<code>content/ContentService</code>校验字段并访问既有sys_news。字典管理与业务读取分为两个Controller；低代码Schema和记录有独立服务范围；不要根据相似页面名推断共用同一个权限。</p><p>正常定位应能找到请求DTO、动作权限、服务字段限制及测试。找不到业务实现时先确认它是否已经移除：资料示例、网站、下载、页面业务模块不能从旧任务或历史路径重新当作当前能力。</p><h2 id="源码依据与恢复" tabindex="-1">源码依据与恢复 <a class="header-anchor" href="#源码依据与恢复" aria-label="Permalink to &quot;源码依据与恢复&quot;">​</a></h2><p>核对 <code>apps/web-ele/src/api/system/news.ts</code>、<code>system-admin/src/main/java/com/xinghuiTec/controller/ContentNewsController.java</code>、<code>content/ContentService.java</code>。当接口路径与旧教程不一致时以当前Controller和API为准，更新文档与调用方；不要建另一套初始架构文件掩盖版本差异。</p>',12)])])}const u=t(r,[["render",c]]);export{h as __pageData,u as default};
